# Какие адреса получат включённые разделы, у которых адреса нет. Только читает.
# Правила те же, что у товаров из 1С (tools/1c-import.py, slug): таблица
# транслитерации записана кодами символов, чтобы в команде была одна латиница,
# и сверена с Python-версией буква в букву. Занятый адрес не перезаписывается:
# в скобках — кем занят и включён ли он, к адресу дописывается номер.
# Последние три строки — открывается ли регистрация в обход запрета в .htaccess.
( cd /var/www/u2934771/data/www/stroigeroi.ru || exit 1; php -r 'mysqli_report(MYSQLI_REPORT_OFF); include "config.php"; $m = @new mysqli(DB_HOSTNAME, DB_USERNAME, DB_PASSWORD, DB_DATABASE, (int)DB_PORT); if ($m->connect_error) { echo "DB: ", $m->connect_error, "\n"; exit(1); } $m->set_charset("utf8"); $q = function ($s) use ($m) { $r = $m->query(str_replace("{p}", DB_PREFIX, $s)); if (!$r) { echo "SQL: ", $m->error, "\n"; return array(); } if ($r === true) return array(); $a = array(); while ($x = $r->fetch_row()) $a[] = $x; return $a; }; $lg = $q("SELECT language_id FROM {p}language WHERE code = (SELECT value FROM {p}setting WHERE `key` = \"config_language\" AND store_id = 0 LIMIT 1) LIMIT 1"); $lang = $lg ? (int)$lg[0][0] : 1; $L = explode(",", "a,b,v,g,d,e,zh,z,i,y,k,l,m,n,o,p,r,s,t,u,f,h,c,ch,sh,sch,,y,,e,yu,ya"); $u = function ($c) { return chr(0xC0 | ($c >> 6)) . chr(0x80 | ($c & 0x3F)); }; $tr = array($u(0x451) => "e", $u(0x401) => "e"); foreach ($L as $i => $v) { $tr[$u(0x430 + $i)] = $v; $tr[$u(0x410 + $i)] = $v; } $slug = function ($t) use ($tr) { $s = trim(preg_replace("/[^a-z0-9]+/", "-", strtolower(strtr($t, $tr))), "-"); if (strlen($s) > 90) { $s = substr($s, 0, 90); $p = strrpos($s, "-"); if ($p !== false) $s = substr($s, 0, $p); } return $s; }; $state = function ($query) use ($q) { if (preg_match("/^(product|category|information)_id=([0-9]+)$/", $query, $mm)) { $r = $q("SELECT status FROM {p}" . $mm[1] . " WHERE " . $mm[1] . "_id = " . (int)$mm[2]); return $r ? ($r[0][0] ? "on" : "off") : "gone"; } return "route"; }; $taken = array(); foreach ($q("SELECT LOWER(keyword), query FROM {p}seo_url WHERE store_id = 0 AND keyword <> \"\"") as $r) $taken[$r[0]] = $r[1]; $rows = $q("SELECT c.category_id, IFNULL((SELECT name FROM {p}category_description WHERE category_id = c.parent_id AND language_id = $lang), \"\"), IFNULL((SELECT name FROM {p}category_description WHERE category_id = c.category_id AND language_id = $lang), \"\") FROM {p}category c WHERE c.status = 1 AND NOT EXISTS (SELECT 1 FROM {p}seo_url s WHERE s.store_id = 0 AND s.keyword <> \"\" AND s.query = CONCAT(\"category_id=\", c.category_id)) ORDER BY c.parent_id <> 0, c.parent_id, c.category_id"); echo "-- language $lang, categories without address: ", count($rows), "\n"; foreach ($rows as $r) { $base = $slug($r[2]); if ($base === "") $base = "razdel"; $kw = $base; $n = 1; $note = ""; if (isset($taken[$kw])) $note = "   (taken by " . $taken[$kw] . ", " . $state($taken[$kw]) . ")"; while (isset($taken[$kw])) { $n++; $kw = $base . "-" . $n; } $taken[$kw] = "category_id=" . $r[0]; echo $r[0], " | ", ($r[1] !== "" ? $r[1] . " > " : ""), $r[2], " | ", $kw, $note, "\n"; }'; for u in create-account forgot-password "index.php?route=account/register"; do echo "$u: $(curl -s -o /dev/null -w '%{http_code}' "https://stroigeroi.ru/$u")"; done )
